using Avalonia;
using Avalonia.Controls;
using Avalonia.Input;
using Avalonia.Interactivity;
using Avalonia.Threading;
using Avalonia.Controls.Primitives;
namespace Transcriptor.Desktop;
internal sealed record AvaloniaMiniModeSnapshot(bool IsRecording,bool IsTranscribing,bool IsError,TimeSpan Elapsed,float MicrophoneLevel,float this.FindControl<ProgressBar>("SystemLevel")!,bool IsPaused,string Status,string SessionTitle,bool IsIdle,bool HasMicrophone,bool HasClient,bool IsPlaying,bool HasPlayback,TimeSpan PlaybackPosition,TimeSpan PlaybackDuration,string PlaybackTrack);
public partial class MiniModeWindow : Window
{
 private readonly MainWindow _main; private readonly DispatcherTimer _timer=new(){Interval=TimeSpan.FromMilliseconds(200)}; private readonly DispatcherTimer _boundsSaveTimer=new(){Interval=TimeSpan.FromMilliseconds(350)}; private bool _allowClose; private bool _updatingSlider;
 public MiniModeWindow(MainWindow main){_main=main;InitializeComponent();Topmost=main.MiniModeAlwaysOnTop;this.FindControl<CheckBox>("TopmostToggle")!.IsChecked=Topmost;Width=Math.Max(MinWidth,main.MiniModeWidth??420);Height=Math.Max(MinHeight,main.MiniModeHeight??150);Position=main.MiniModeLeft is double left&&main.MiniModeTop is double top?new PixelPoint((int)left,(int)top):new PixelPoint(24,24);_timer.Tick+=(_,_)=>RefreshSnapshot();_boundsSaveTimer.Tick+=(_,_)=>{_boundsSaveTimer.Stop();SaveBounds();};Opened+=(_,_)=>{_timer.Start();RefreshSnapshot();};PositionChanged+=(_,_)=>DebounceBoundsSave();SizeChanged+=(_,_)=>DebounceBoundsSave();}
 private void InitializeComponent()=>Avalonia.Markup.Xaml.AvaloniaXamlLoader.Load(this);
 private void DebounceBoundsSave(){_boundsSaveTimer.Stop();_boundsSaveTimer.Start();}
 private void Root_PointerPressed(object? s,PointerPressedEventArgs e){if(e.GetCurrentPoint(this).Properties.IsLeftButtonPressed&&e.Source is not Button)BeginMoveDrag(e);}
 private void RefreshSnapshot(){AvaloniaMiniModeSnapshot? s;try{s=_main.GetMiniModeSnapshot();}catch(Exception ex){this.FindControl<TextBlock>("StateText")!.Text="⚠ ERROR";this.FindControl<TextBlock>("SessionText")!.Text="No se pudo actualizar el estado; reintentando…";System.Diagnostics.Debug.WriteLine(ex);return;}if(s is null)return;if(s.IsTranscribing){this.FindControl<TextBlock>("StateText")!.Text="⏳ TRANSCRIBIENDO";this.FindControl<TextBlock>("StateText")!.Foreground=Avalonia.Media.Brushes.Orange;this.FindControl<TextBlock>("ElapsedText")!.Text=string.Empty;this.FindControl<Grid>("RecordingPanel")!.IsVisible=false;this.FindControl<Grid>("RecordingControls")!.IsVisible=false;this.FindControl<StackPanel>("IdlePanel")!.IsVisible=false;this.FindControl<StackPanel>("TranscriptionPanel")!.IsVisible=true;this.FindControl<TextBlock>("TranscriptionText")!.Text=s.Status;this.FindControl<Button>("CancelTranscriptionButton")!.IsEnabled=!_main.IsMiniModeTranscriptionCancellationRequested;return;}this.FindControl<StackPanel>("TranscriptionPanel")!.IsVisible=false;this.FindControl<StackPanel>("IdlePanel")!.IsVisible=s.IsIdle;this.FindControl<Grid>("RecordingPanel")!.IsVisible=!s.IsIdle;this.FindControl<Grid>("RecordingControls")!.IsVisible=!s.IsIdle;if(s.IsIdle){this.FindControl<TextBlock>("StateText")!.Text="● LISTO";this.FindControl<TextBlock>("StateText")!.Foreground=Avalonia.Media.Brushes.LightGreen;this.FindControl<TextBlock>("ElapsedText")!.Text=string.Empty;this.FindControl<TextBlock>("IdleSessionText")!.Text=s.SessionTitle;this.FindControl<Button>("PlayMicrophoneButton")!.IsEnabled=s.HasMicrophone;this.FindControl<Button>("PlayClientButton")!.IsEnabled=s.HasClient;this.FindControl<Button>("StopPlaybackButton")!.IsEnabled=s.IsPlaying;this.FindControl<Slider>("PlaybackSeekSlider")!.Maximum=Math.Max(1,s.PlaybackDuration.TotalSeconds);this.FindControl<Slider>("PlaybackSeekSlider")!.IsEnabled=s.HasPlayback&&s.PlaybackDuration>TimeSpan.Zero;if(!this.FindControl<Slider>("PlaybackSeekSlider")!.IsPointerOver&&!this.FindControl<Slider>("PlaybackSeekSlider")!.IsFocused){_updatingSlider=true;this.FindControl<Slider>("PlaybackSeekSlider")!.Value=Math.Clamp(s.PlaybackPosition.TotalSeconds,0,this.FindControl<Slider>("PlaybackSeekSlider")!.Maximum);_updatingSlider=false;}this.FindControl<TextBlock>("PlaybackCurrentText")!.Text=FormatTime(s.PlaybackPosition);this.FindControl<TextBlock>("PlaybackDurationText")!.Text=FormatTime(s.PlaybackDuration);this.FindControl<TextBlock>("PlaybackTrackText")!.Text=s.HasPlayback?"Reproduciendo: "+s.PlaybackTrack:"Sin reproducción";return;}this.FindControl<TextBlock>("StateText")!.Text=s.IsError?"⚠ ERROR":s.IsPaused?"Ⅱ PAUSADO":"● REC";this.FindControl<TextBlock>("StateText")!.Foreground=s.IsError?Avalonia.Media.Brushes.OrangeRed:s.IsPaused?Avalonia.Media.Brushes.Orange:Avalonia.Media.Brushes.LightCoral;long sec=Math.Max(0,(long)s.Elapsed.TotalSeconds);this.FindControl<TextBlock>("ElapsedText")!.Text=$"{sec/3600:00}:{sec/60%60:00}:{sec%60:00}";this.FindControl<ProgressBar>("MicLevel")!.Value=Math.Clamp(s.MicrophoneLevel*100,0,100);this.FindControl<ProgressBar>("SystemLevel")!.Value=Math.Clamp(s.this.FindControl<ProgressBar>("SystemLevel")!*100,0,100);this.FindControl<TextBlock>("MicLevelText")!.Text=$"{this.FindControl<ProgressBar>("MicLevel")!.Value:0}%";this.FindControl<TextBlock>("SystemLevelText")!.Text=$"{this.FindControl<ProgressBar>("SystemLevel")!.Value:0}%";this.FindControl<Button>("PauseButton")!.Content=s.IsPaused?"▶ Reanudar":"Ⅱ Pausar";this.FindControl<Button>("PauseButton")!.IsEnabled=!s.IsError;this.FindControl<TextBlock>("SessionText")!.Text=s.SessionTitle;}
 private static string FormatTime(TimeSpan t){long s=Math.Max(0,(long)t.TotalSeconds);return $"{s/60:00}:{s%60:00}";}
 private void Pause_Click(object? sender,RoutedEventArgs e){try{if(_main.GetMiniModeSnapshot()?.IsPaused==true)_main.ResumeRecordingFromMiniMode();else _main.PauseRecordingFromMiniMode();}catch(Exception ex){_main.ReportMiniModeError("No se pudo pausar o reanudar: "+ex.Message);}RefreshSnapshot();}
 private async void Stop_Click(object? sender,RoutedEventArgs e){if(!await _main.ConfirmMiniModeStopAsync(this))return;this.FindControl<Button>("PauseButton")!.IsEnabled=false;this.FindControl<Button>("StopButton")!.IsEnabled=false;try{await _main.StopRecordingFromMiniModeAsync();}catch(Exception ex){_main.ReportMiniModeError("No se pudo detener la grabación: "+ex.Message);}finally{RefreshSnapshot();}}
 private void PlayMicrophone_Click(object? s,RoutedEventArgs e){_main.PlayMicrophoneFromMiniMode();RefreshSnapshot();} private void PlayClient_Click(object? s,RoutedEventArgs e){_main.PlayClientFromMiniMode();RefreshSnapshot();} private void StopPlayback_Click(object? s,RoutedEventArgs e){_main.StopPlaybackFromMiniMode();RefreshSnapshot();}
 private void PlaybackSeekSlider_ValueChanged(object? s,RangeBaseValueChangedEventArgs e){if(!_updatingSlider&&(this.FindControl<Slider>("PlaybackSeekSlider")!.IsPointerOver||this.FindControl<Slider>("PlaybackSeekSlider")!.IsFocused)&&_main.GetMiniModeSnapshot()?.HasPlayback==true)_main.SeekPlaybackFromMiniMode(TimeSpan.FromSeconds(this.FindControl<Slider>("PlaybackSeekSlider")!.Value));}
 private void CancelTranscription_Click(object? s,RoutedEventArgs e){this.FindControl<Button>("CancelTranscriptionButton")!.IsEnabled=false;this.FindControl<TextBlock>("TranscriptionText")!.Text="Cancelando transcripción…";_main.CancelTranscriptionFromMiniMode();}
 private void Topmost_Click(object? s,RoutedEventArgs e){Topmost=this.FindControl<CheckBox>("TopmostToggle")!.IsChecked==true;_main.UpdateMiniModePreferences(Topmost,Position.X,Position.Y,Width,Height);}
 private void Expand_Click(object? s,RoutedEventArgs e)=>_main.ExpandFromMiniMode(this); private void CloseMini_Click(object? s,RoutedEventArgs e)=>_main.CloseMiniModeFromWindow(this);
 private void MiniWindow_KeyDown(object? s,KeyEventArgs e){if(e.KeyModifiers==KeyModifiers.None&&e.Key==Key.Space&&_main.GetMiniModeSnapshot()?.IsRecording==true){Pause_Click(s,new RoutedEventArgs());e.Handled=true;}else if(e.KeyModifiers==KeyModifiers.Control&&e.Key==Key.M){Expand_Click(s,new RoutedEventArgs());e.Handled=true;}else if(e.KeyModifiers==(KeyModifiers.Control|KeyModifiers.Shift)&&e.Key==Key.S&&_main.GetMiniModeSnapshot()?.IsRecording==true){Stop_Click(s,new RoutedEventArgs());e.Handled=true;}}
 private void MiniWindow_Closed(object? s,EventArgs e){_timer.Stop();_boundsSaveTimer.Stop();if(!_allowClose)_main.MiniModeWindowClosed(this);} internal void CloseFromMain(){_allowClose=true;_timer.Stop();_boundsSaveTimer.Stop();SaveBounds();Close();}
 internal void SaveBounds()=>_main.UpdateMiniModePreferences(Topmost,Position.X,Position.Y,Width,Height);
}